effect.shader:
    vec4 newLayer( vec4 a, vec4 b) {
    return a * (1. - b.a) + b;
    }

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord.xy

   /////////////////////////

   // One streak gather, capped at NTAPS taps. The tap stride is scaled by the capped
   // count (1/(n-1) instead of 1/(nFull-1)), so the streak still ends at exactly
   // 0.5 * velocity - the length is unchanged, only the tap density drops.
   const int NTAPS = 32;

   vec4 streakBlur( vec2 velocity, vec2 uv, vec2 texelSize ) {
        float speed  = length(velocity / max(texelSize, vec2(1e-8)));
        int   nFull  = int(clamp(speed, 1.01, 100.01));
        int   n      = nFull > NTAPS ? NTAPS : nFull;
        float invDen = 1.0 / float(max(n - 1, 1));

        vec4 outColor = texture2DCv(xdist.texture, uv);
        for (int i = 1; i < NTAPS; i++) {
            if (i >= n) break;
            vec2 sampleCoord = uv - velocity * (float(i) * invDen - 0.5);
            float insideTexture = step(0.0,sampleCoord.x) * step(sampleCoord.x,1.0) * step(0.0,sampleCoord.y) * step(sampleCoord.y,1.0);
            outColor += texture2DCv(xdist.texture, sampleCoord) * insideTexture;
        }
        return outColor / float(n);
   }

   /////////////////////////
    void main ()
    {
            vec4 oricol = texture2DCv(inputImg.texture,acScreenNorm);

            // Nothing to gather: the result is the untouched layer either way.
            if (strength <= 0.0011) { gl_FragColor = oricol; return; }
            // Every streak is multiplied by alpha, so at alpha 0 the gather is provably zero.
            if (alpha <= 0.0)       { gl_FragColor = oricol * oricol.a; return; }

            vec2  texelSize = 1.0 / max(getTexSize(xdist.size), vec2(1.0));
            vec2  uv        = acScreenNorm.st;
            float aspect    = acScreenSize.y / acScreenSize.x;

            // Iterations widen the streak (longer stride) instead of re-running the
            // whole brightpass + 4-direction gather once per iteration.
            float len = strength * max(float(iter), 1.0);

            const float D = 0.70710678;   // cos/sin 45
            float dx = D * len * aspect;
            float dy = D * len;

            vec4 d1 = vec4(0.0); vec4 d2 = vec4(0.0);
            vec4 d4 = vec4(0.0); vec4 d5 = vec4(0.0);

            // Only gather the directions the selected Type actually reads.
            if (type != 1) {                                        // 45 / 135  (CROSS, STAR)
                d1 = streakBlur(vec2( dx, -dy), uv, texelSize);
                d2 = streakBlur(vec2(-dx, -dy), uv, texelSize);
            }
            if (type != 0) {                                        // 0 / 90    (PLUS, STAR)
                d4 = streakBlur(vec2( len * aspect, 0.0), uv, texelSize);
                d5 = streakBlur(vec2( 0.0,        -len), uv, texelSize);
            }

            // float balpha = autob ? clamp(alpha, 1.0, 0.0) * speed : alpha;

            // vec4 d3 = max(d1,d2) * balpha;
            // vec4 d6 = max(d4,d5) * balpha;
            // vec4 d7 = max(d3,d6) * balpha;

            vec4 d3 = max(d1,d2) * alpha;
            vec4 d6 = max(d4,d5) * alpha;
            vec4 d7 = max(d3,d6) * alpha;

            vec4 d8 = d3;
            if(type==1) {d8 = d6;}
            else if(type==2) {d8 = d7;}

            // gl_FragColor = strength > 0.0011 ? (oricol+d3) * oricol.a : oricol;
            gl_FragColor = (oricol+d8) * oricol.a;
    }
